#!/usr/bin/env bash
# AI generated by claude.ai (https://claude.ai)
# =============================================================================
# aws_setup.sh — AWS setup for the Emergency Dispatch Data Platform (capstone)
#
# Creates and verifies everything ADR-0002 / D-27 need in YOUR AWS account:
#   - S3 Bronze bucket (versioning, Block Public Access, SSE-S3, TLS-only)
#   - IAM user  <project>-ingestion          (write raw/ parquet/ manifests/ state/; no delete)
#   - IAM role  <project>-snowflake-s3-read  (read only; trusted by Snowflake only)
#   - Monthly cost budget with e-mail alerts
#   - Ingestion access key written to .env (chmod 600, never printed)
#
# Safe to rerun: every step checks what exists and only creates or updates
# what differs. Use it again whenever you need to reconfigure.
#
# Manual steps (console) are in AWS_SETUP_MANUAL.md. Do M1-M4 before the
# first run; M5 belongs between 'setup' and 'snowflake-trust'.
#
# Commands
#   ./aws_setup.sh preflight              checks identity, region, CLI version
#   ./aws_setup.sh setup                  bucket, policies, user, role, budget
#   ./aws_setup.sh keys                   ingestion access key → .env
#   ./aws_setup.sh keys --rotate          new key → .env, old key deleted
#   ./aws_setup.sh snowflake-trust <STORAGE_AWS_IAM_USER_ARN> <STORAGE_AWS_EXTERNAL_ID>
#                                         lock the Snowflake role to Snowflake (after M5)
#   ./aws_setup.sh verify                 tests IA-01 … IA-11, IA-14
#   ./aws_setup.sh verify --roundtrip     + IA-12 (real write/read with the .env key)
#   ./aws_setup.sh verify --idempotency   + IA-13 (reruns setup, expects 0 changes)
#   ./aws_setup.sh status                 short overview of what exists
#   ./aws_setup.sh all                    preflight + setup + keys + verify
#
# Requirements: AWS CLI v2, python3, bash 3.2+ (macOS default is fine).
# =============================================================================

set -euo pipefail

# ----------------------------- configuration ---------------------------------
# Override any value with an environment variable, e.g.
#   BUDGET_EMAIL=me@example.com ./aws_setup.sh setup
AWS_PROFILE="${AWS_PROFILE:-capstone-admin}"
REGION="${REGION:-eu-central-1}"
PROJECT="${PROJECT:-sf-dispatch}"
BUCKET="${BUCKET:-}"                      # default: <project>-bronze-<account id>
INGEST_USER="${INGEST_USER:-${PROJECT}-ingestion}"
SF_ROLE="${SF_ROLE:-${PROJECT}-snowflake-s3-read}"
BUDGET_NAME="${BUDGET_NAME:-${PROJECT}-monthly}"
BUDGET_LIMIT_USD="${BUDGET_LIMIT_USD:-10}"
BUDGET_EMAIL="${BUDGET_EMAIL:-}"
ENV_FILE="${ENV_FILE:-./.env}"

# Prefixes (ADR-0002 decision 4, D-27)
INGEST_WRITE_PREFIXES="raw parquet manifests state"
SF_READ_PREFIXES="raw parquet events"
PENDING_EXTERNAL_ID="pending-snowflake-setup"

export AWS_PROFILE
export AWS_PAGER=""

# ----------------------------- helpers ---------------------------------------
CHANGES=0
say()     { printf '%s\n' "$*"; }
ok()      { printf '  OK       %s\n' "$*"; }
created() { printf '  CREATED  %s\n' "$*"; CHANGES=$((CHANGES + 1)); }
updated() { printf '  UPDATED  %s\n' "$*"; CHANGES=$((CHANGES + 1)); }
die()     { printf 'ERROR: %s\n' "$*" >&2; exit 1; }

aws_r() { aws --region "$REGION" "$@"; }

ACCOUNT_ID=""
load_account() {
  ACCOUNT_ID="$(aws sts get-caller-identity --query Account --output text)"
  [ -n "$BUCKET" ] || BUCKET="${PROJECT}-bronze-${ACCOUNT_ID}"
}

user_arn() { printf 'arn:aws:iam::%s:user/%s' "$ACCOUNT_ID" "$INGEST_USER"; }
role_arn() { printf 'arn:aws:iam::%s:role/%s' "$ACCOUNT_ID" "$SF_ROLE"; }

# Compact JSON (strip whitespace); used for simple text checks
compact() { tr -d ' \n\t'; }

# Canonical JSON (sorted keys, no spaces) so stored and desired policies compare
# equal even if AWS returns them in a different key order. Empty input → empty.
canon() {
  python3 -c 'import json,sys
d=sys.stdin.read().strip()
print(json.dumps(json.loads(d),sort_keys=True,separators=(",",":")) if d else "")' 2>/dev/null || true
}

# ----------------------------- policy documents ------------------------------
json_list() { # json_list "a b" "arn:...:%s/*" → ["arn..a/*","arn..b/*"]
  local items="$1" fmt="$2" out="" i
  for i in $items; do
    out="${out}$(printf "\"${fmt}\"" "$i"),"
  done
  printf '[%s]' "${out%,}"
}

ingest_policy() {
  cat <<EOF
{
  "Version": "2012-10-17",
  "Statement": [
    {
      "Sid": "WriteAndReadOwnPrefixes",
      "Effect": "Allow",
      "Action": ["s3:PutObject", "s3:GetObject", "s3:AbortMultipartUpload", "s3:ListMultipartUploadParts"],
      "Resource": $(json_list "$INGEST_WRITE_PREFIXES" "arn:aws:s3:::${BUCKET}/%s/*")
    },
    {
      "Sid": "ListOwnPrefixes",
      "Effect": "Allow",
      "Action": "s3:ListBucket",
      "Resource": "arn:aws:s3:::${BUCKET}",
      "Condition": { "StringLike": { "s3:prefix": $(json_list "$INGEST_WRITE_PREFIXES" "%s/*") } }
    },
    {
      "Sid": "BucketLocation",
      "Effect": "Allow",
      "Action": "s3:GetBucketLocation",
      "Resource": "arn:aws:s3:::${BUCKET}"
    }
  ]
}
EOF
}

sf_read_policy() {
  cat <<EOF
{
  "Version": "2012-10-17",
  "Statement": [
    {
      "Sid": "ReadBronze",
      "Effect": "Allow",
      "Action": ["s3:GetObject", "s3:GetObjectVersion"],
      "Resource": $(json_list "$SF_READ_PREFIXES" "arn:aws:s3:::${BUCKET}/%s/*")
    },
    {
      "Sid": "ListBronze",
      "Effect": "Allow",
      "Action": "s3:ListBucket",
      "Resource": "arn:aws:s3:::${BUCKET}",
      "Condition": { "StringLike": { "s3:prefix": $(json_list "$SF_READ_PREFIXES" "%s/*") } }
    },
    {
      "Sid": "BucketLocation",
      "Effect": "Allow",
      "Action": "s3:GetBucketLocation",
      "Resource": "arn:aws:s3:::${BUCKET}"
    }
  ]
}
EOF
}

trust_policy() { # trust_policy <principal arn> <external id>
  cat <<EOF
{
  "Version": "2012-10-17",
  "Statement": [
    {
      "Effect": "Allow",
      "Principal": { "AWS": "$1" },
      "Action": "sts:AssumeRole",
      "Condition": { "StringEquals": { "sts:ExternalId": "$2" } }
    }
  ]
}
EOF
}

bucket_policy() {
  cat <<EOF
{
  "Version": "2012-10-17",
  "Statement": [
    {
      "Sid": "DenyInsecureTransport",
      "Effect": "Deny",
      "Principal": "*",
      "Action": "s3:*",
      "Resource": ["arn:aws:s3:::${BUCKET}", "arn:aws:s3:::${BUCKET}/*"],
      "Condition": { "Bool": { "aws:SecureTransport": "false" } }
    }
  ]
}
EOF
}

# ----------------------------- preflight -------------------------------------
cmd_preflight() {
  say "== Preflight (profile: $AWS_PROFILE, region: $REGION)"
  command -v aws >/dev/null || die "AWS CLI not found"
  aws --version 2>&1 | grep -q 'aws-cli/2' || die "AWS CLI v2 required ($(aws --version 2>&1))"
  ok "AWS CLI v2"
  command -v python3 >/dev/null || die "python3 not found (used to compare policy JSON)"

  local arn
  arn="$(aws sts get-caller-identity --query Arn --output text 2>/dev/null)" \
    || die "Profile '$AWS_PROFILE' cannot authenticate. Do manual steps M3-M4."
  case "$arn" in
    *:root) die "Profile '$AWS_PROFILE' is the ROOT user. Use an admin IAM user (M2-M4)." ;;
  esac
  ok "Caller: $arn"

  load_account
  ok "Account: $ACCOUNT_ID"
  ok "Bucket name: $BUCKET"
}

# ----------------------------- setup -----------------------------------------
setup_bucket() {
  say "== S3 bucket"
  if aws_r s3api head-bucket --bucket "$BUCKET" >/dev/null 2>&1; then
    ok "bucket $BUCKET exists"
  else
    if [ "$REGION" = "us-east-1" ]; then
      aws_r s3api create-bucket --bucket "$BUCKET" >/dev/null
    else
      aws_r s3api create-bucket --bucket "$BUCKET" \
        --create-bucket-configuration "LocationConstraint=$REGION" >/dev/null
    fi
    created "bucket $BUCKET ($REGION)"
  fi

  # Block Public Access (all four)
  local bpa
  bpa="$(aws_r s3api get-public-access-block --bucket "$BUCKET" \
    --query 'PublicAccessBlockConfiguration.[BlockPublicAcls,IgnorePublicAcls,BlockPublicPolicy,RestrictPublicBuckets]' \
    --output text 2>/dev/null || true)"
  if [ "$(printf '%s' "$bpa" | tr -s '\t ' ' ')" = "True True True True" ]; then
    ok "Block Public Access on"
  else
    aws_r s3api put-public-access-block --bucket "$BUCKET" --public-access-block-configuration \
      BlockPublicAcls=true,IgnorePublicAcls=true,BlockPublicPolicy=true,RestrictPublicBuckets=true
    updated "Block Public Access on"
  fi

  # Object ownership: bucket owner enforced (ACLs disabled)
  local own
  own="$(aws_r s3api get-bucket-ownership-controls --bucket "$BUCKET" \
    --query 'OwnershipControls.Rules[0].ObjectOwnership' --output text 2>/dev/null || true)"
  if [ "$own" = "BucketOwnerEnforced" ]; then
    ok "ACLs disabled (BucketOwnerEnforced)"
  else
    aws_r s3api put-bucket-ownership-controls --bucket "$BUCKET" \
      --ownership-controls 'Rules=[{ObjectOwnership=BucketOwnerEnforced}]'
    updated "ACLs disabled (BucketOwnerEnforced)"
  fi

  # Versioning (D-27: watermark history)
  local ver
  ver="$(aws_r s3api get-bucket-versioning --bucket "$BUCKET" --query Status --output text 2>/dev/null || true)"
  if [ "$ver" = "Enabled" ]; then
    ok "versioning Enabled"
  else
    aws_r s3api put-bucket-versioning --bucket "$BUCKET" --versioning-configuration Status=Enabled
    updated "versioning Enabled"
  fi

  # Default encryption SSE-S3
  local enc
  enc="$(aws_r s3api get-bucket-encryption --bucket "$BUCKET" \
    --query 'ServerSideEncryptionConfiguration.Rules[0].ApplyServerSideEncryptionByDefault.SSEAlgorithm' \
    --output text 2>/dev/null || true)"
  if [ "$enc" = "AES256" ]; then
    ok "default encryption SSE-S3"
  else
    aws_r s3api put-bucket-encryption --bucket "$BUCKET" --server-side-encryption-configuration \
      '{"Rules":[{"ApplyServerSideEncryptionByDefault":{"SSEAlgorithm":"AES256"},"BucketKeyEnabled":true}]}'
    updated "default encryption SSE-S3"
  fi

  # Bucket policy: TLS only
  local want have
  want="$(bucket_policy | canon)"
  have="$( (aws_r s3api get-bucket-policy --bucket "$BUCKET" --query Policy --output text 2>/dev/null || true) | canon)"
  if [ "$have" = "$want" ]; then
    ok "bucket policy (TLS only)"
  else
    aws_r s3api put-bucket-policy --bucket "$BUCKET" --policy "$(bucket_policy)"
    updated "bucket policy (TLS only)"
  fi
}

setup_ingest_user() {
  say "== IAM user $INGEST_USER"
  if aws iam get-user --user-name "$INGEST_USER" >/dev/null 2>&1; then
    ok "user exists"
  else
    aws iam create-user --user-name "$INGEST_USER" \
      --tags "Key=project,Value=$PROJECT" >/dev/null
    created "user $INGEST_USER"
  fi

  local want have
  want="$(ingest_policy | canon)"
  have="$( (aws iam get-user-policy --user-name "$INGEST_USER" --policy-name "${PROJECT}-ingestion-s3" \
    --query PolicyDocument --output json 2>/dev/null || true) | canon)"
  if [ -n "$have" ] && [ "$have" = "$want" ]; then
    ok "inline policy ${PROJECT}-ingestion-s3"
  else
    aws iam put-user-policy --user-name "$INGEST_USER" \
      --policy-name "${PROJECT}-ingestion-s3" --policy-document "$(ingest_policy)"
    if [ -n "$have" ]; then updated "inline policy ${PROJECT}-ingestion-s3"
    else created "inline policy ${PROJECT}-ingestion-s3"; fi
  fi
}

setup_sf_role() {
  say "== IAM role $SF_ROLE"
  if aws iam get-role --role-name "$SF_ROLE" >/dev/null 2>&1; then
    ok "role exists (trust policy is managed by 'snowflake-trust')"
  else
    # Placeholder trust: own account + a dummy external ID. Nobody outside the
    # account can assume it until 'snowflake-trust' sets Snowflake's ARN.
    aws iam create-role --role-name "$SF_ROLE" \
      --assume-role-policy-document "$(trust_policy "arn:aws:iam::${ACCOUNT_ID}:root" "$PENDING_EXTERNAL_ID")" \
      --description "Snowflake storage integration: read-only access to the Bronze bucket" \
      --tags "Key=project,Value=$PROJECT" >/dev/null
    created "role $SF_ROLE (trust pending Snowflake, step M5)"
  fi

  local want have
  want="$(sf_read_policy | canon)"
  have="$( (aws iam get-role-policy --role-name "$SF_ROLE" --policy-name "${PROJECT}-snowflake-s3-read" \
    --query PolicyDocument --output json 2>/dev/null || true) | canon)"
  if [ -n "$have" ] && [ "$have" = "$want" ]; then
    ok "inline policy ${PROJECT}-snowflake-s3-read"
  else
    aws iam put-role-policy --role-name "$SF_ROLE" \
      --policy-name "${PROJECT}-snowflake-s3-read" --policy-document "$(sf_read_policy)"
    if [ -n "$have" ]; then updated "inline policy ${PROJECT}-snowflake-s3-read"
    else created "inline policy ${PROJECT}-snowflake-s3-read"; fi
  fi
  say "  Role ARN for Snowflake STORAGE_AWS_ROLE_ARN: $(role_arn)"
}

setup_budget() {
  say "== Budget $BUDGET_NAME"
  [ -n "$BUDGET_EMAIL" ] || die "Set BUDGET_EMAIL, e.g. BUDGET_EMAIL=you@example.com ./aws_setup.sh setup"

  local have
  have="$(aws budgets describe-budget --region us-east-1 --account-id "$ACCOUNT_ID" \
    --budget-name "$BUDGET_NAME" --query 'Budget.BudgetLimit.Amount' --output text 2>/dev/null || true)"

  local budget_json
  budget_json="{\"BudgetName\":\"$BUDGET_NAME\",\"BudgetLimit\":{\"Amount\":\"$BUDGET_LIMIT_USD\",\"Unit\":\"USD\"},\"TimeUnit\":\"MONTHLY\",\"BudgetType\":\"COST\"}"

  if [ -z "$have" ]; then
    local sub="[{\"SubscriptionType\":\"EMAIL\",\"Address\":\"$BUDGET_EMAIL\"}]"
    aws budgets create-budget --region us-east-1 --account-id "$ACCOUNT_ID" \
      --budget "$budget_json" \
      --notifications-with-subscribers "[
        {\"Notification\":{\"NotificationType\":\"ACTUAL\",\"ComparisonOperator\":\"GREATER_THAN\",\"Threshold\":50,\"ThresholdType\":\"PERCENTAGE\"},\"Subscribers\":$sub},
        {\"Notification\":{\"NotificationType\":\"ACTUAL\",\"ComparisonOperator\":\"GREATER_THAN\",\"Threshold\":100,\"ThresholdType\":\"PERCENTAGE\"},\"Subscribers\":$sub},
        {\"Notification\":{\"NotificationType\":\"FORECASTED\",\"ComparisonOperator\":\"GREATER_THAN\",\"Threshold\":100,\"ThresholdType\":\"PERCENTAGE\"},\"Subscribers\":$sub}
      ]"
    created "budget \$$BUDGET_LIMIT_USD/month; e-mail at 50% and 100% actual, 100% forecast"
  elif [ "${have%%.*}" != "${BUDGET_LIMIT_USD%%.*}" ]; then
    aws budgets update-budget --region us-east-1 --account-id "$ACCOUNT_ID" --new-budget "$budget_json"
    updated "budget limit \$$have → \$$BUDGET_LIMIT_USD (alert e-mails unchanged)"
  else
    ok "budget \$$have/month"
  fi
}

cmd_setup() {
  cmd_preflight
  setup_bucket
  setup_ingest_user
  setup_sf_role
  setup_budget
  say ""
  say "Setup finished: $CHANGES change(s)."
  say "Next: ./aws_setup.sh keys   (if the ingestion key is not in $ENV_FILE yet)"
}

# ----------------------------- keys ------------------------------------------
env_get() { [ -f "$ENV_FILE" ] && grep -E "^$1=" "$ENV_FILE" | tail -n1 | cut -d= -f2- || true; }

env_set() { # env_set KEY VALUE  (keeps all other lines, e.g. SODA_APP_TOKEN)
  local tmp
  umask 077
  tmp="$(mktemp)"
  [ -f "$ENV_FILE" ] && grep -vE "^$1=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$1" "$2" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  chmod 600 "$ENV_FILE"
}

cmd_keys() {
  cmd_preflight
  local rotate="${1:-}"
  local current_id
  current_id="$(env_get AWS_ACCESS_KEY_ID)"
  local existing
  existing="$(aws iam list-access-keys --user-name "$INGEST_USER" --query 'AccessKeyMetadata[].AccessKeyId' --output text)"

  if [ "$rotate" != "--rotate" ] && [ -n "$current_id" ] && printf '%s' "$existing" | grep -qw "$current_id"; then
    ok "ingestion key already in $ENV_FILE (use 'keys --rotate' for a new one)"
    return
  fi

  local n
  n="$(printf '%s' "$existing" | wc -w | tr -d ' ')"
  if [ "$n" -ge 2 ]; then
    die "User has 2 keys already (AWS maximum). Delete an unused one in the console, then rerun."
  fi

  local pair
  pair="$(aws iam create-access-key --user-name "$INGEST_USER" \
    --query 'AccessKey.[AccessKeyId,SecretAccessKey]' --output text)"
  env_set AWS_ACCESS_KEY_ID "$(printf '%s' "$pair" | cut -f1)"
  env_set AWS_SECRET_ACCESS_KEY "$(printf '%s' "$pair" | cut -f2)"
  env_set AWS_DEFAULT_REGION "$REGION"
  env_set S3_BUCKET "$BUCKET"
  unset pair
  created "access key for $INGEST_USER written to $ENV_FILE (chmod 600; value not shown)"

  if [ "$rotate" = "--rotate" ] && [ -n "$current_id" ] && printf '%s' "$existing" | grep -qw "$current_id"; then
    aws iam delete-access-key --user-name "$INGEST_USER" --access-key-id "$current_id"
    updated "old key deleted"
  fi
}

# ----------------------------- snowflake trust -------------------------------
cmd_snowflake_trust() {
  [ $# -eq 2 ] || die "Usage: ./aws_setup.sh snowflake-trust <STORAGE_AWS_IAM_USER_ARN> <STORAGE_AWS_EXTERNAL_ID>"
  case "$1" in arn:aws:iam::*:user/*) ;; *) die "First argument must be an IAM user ARN from DESC INTEGRATION" ;; esac
  cmd_preflight
  aws iam update-assume-role-policy --role-name "$SF_ROLE" --policy-document "$(trust_policy "$1" "$2")"
  updated "trust policy of $SF_ROLE → Snowflake principal + external ID"
}

# ----------------------------- verify (tests) --------------------------------
PASS=0; FAIL=0; PEND=0
t_pass() { printf '  PASS     %-6s %s\n' "$1" "$2"; PASS=$((PASS + 1)); }
t_fail() { printf '  FAIL     %-6s %s\n' "$1" "$2"; FAIL=$((FAIL + 1)); }
t_pend() { printf '  PENDING  %-6s %s\n' "$1" "$2"; PEND=$((PEND + 1)); }

simulate() { # simulate <principal arn> <action> <resource arn> [s3 prefix]
  local ctx=()
  if [ -n "${4:-}" ]; then
    ctx=(--context-entries "ContextKeyName=s3:prefix,ContextKeyValues=$4,ContextKeyType=string")
  fi
  aws iam simulate-principal-policy --policy-source-arn "$1" --action-names "$2" \
    --resource-arns "$3" "${ctx[@]+"${ctx[@]}"}" \
    --query 'EvaluationResults[0].EvalDecision' --output text 2>/dev/null || echo error
}

expect() { # expect <id> <label> <want: allowed|denied> <principal> <action> <resource> [prefix]
  local got
  got="$(simulate "$4" "$5" "$6" "${7:-}")"
  case "$3:$got" in
    allowed:allowed) t_pass "$1" "$2" ;;
    denied:implicitDeny|denied:explicitDeny) t_pass "$1" "$2" ;;
    *) t_fail "$1" "$2 (expected $3, got $got)" ;;
  esac
}

cmd_verify() {
  local roundtrip="" idem=""
  for a in "$@"; do
    case "$a" in --roundtrip) roundtrip=1 ;; --idempotency) idem=1 ;; *) die "Unknown option $a" ;; esac
  done
  cmd_preflight
  say "== Verify"
  local B="arn:aws:s3:::${BUCKET}" U R
  U="$(user_arn)"; R="$(role_arn)"

  # --- configuration ---
  local loc
  loc="$(aws_r s3api get-bucket-location --bucket "$BUCKET" --query LocationConstraint --output text 2>/dev/null || echo missing)"
  [ "$loc" = "None" ] && loc="us-east-1"
  [ "$loc" = "$REGION" ] && t_pass IA-01 "bucket in $REGION" || t_fail IA-01 "bucket region is '$loc', expected $REGION"

  [ "$(aws_r s3api get-bucket-versioning --bucket "$BUCKET" --query Status --output text 2>/dev/null)" = "Enabled" ] \
    && t_pass IA-02 "versioning Enabled" || t_fail IA-02 "versioning not Enabled"

  [ "$(aws_r s3api get-public-access-block --bucket "$BUCKET" \
      --query 'PublicAccessBlockConfiguration.[BlockPublicAcls,IgnorePublicAcls,BlockPublicPolicy,RestrictPublicBuckets]' \
      --output text 2>/dev/null | tr -s '\t ' ' ')" = "True True True True" ] \
    && t_pass IA-03 "Block Public Access: all 4 on" || t_fail IA-03 "Block Public Access incomplete"

  [ "$(aws_r s3api get-bucket-encryption --bucket "$BUCKET" \
      --query 'ServerSideEncryptionConfiguration.Rules[0].ApplyServerSideEncryptionByDefault.SSEAlgorithm' \
      --output text 2>/dev/null)" = "AES256" ] \
    && t_pass IA-04 "default encryption SSE-S3" || t_fail IA-04 "default encryption missing"

  local nb
  nb="$(aws budgets describe-budget --region us-east-1 --account-id "$ACCOUNT_ID" --budget-name "$BUDGET_NAME" \
    --query 'Budget.BudgetName' --output text 2>/dev/null || true)"
  [ "$nb" = "$BUDGET_NAME" ] && t_pass IA-05 "budget $BUDGET_NAME exists" || t_fail IA-05 "budget missing"

  [ "$(aws iam get-account-summary --query 'SummaryMap.AccountAccessKeysPresent' --output text)" = "0" ] \
    && t_pass IA-06 "root has no access keys" || t_fail IA-06 "root HAS access keys (manual step M2)"

  # --- least privilege (policy simulation; touches no data) ---
  local p
  for p in $INGEST_WRITE_PREFIXES; do
    expect IA-07 "ingestion can write $p/"       allowed "$U" s3:PutObject "$B/$p/x"
  done
  expect IA-07 "ingestion can list state/"       allowed "$U" s3:ListBucket "$B" "state/x"
  expect IA-08 "ingestion cannot delete objects" denied  "$U" s3:DeleteObject "$B/raw/x"
  expect IA-08 "ingestion cannot write events/"  denied  "$U" s3:PutObject "$B/events/x"
  expect IA-08 "ingestion cannot list events/"   denied  "$U" s3:ListBucket "$B" "events/x"
  expect IA-09 "ingestion cannot change IAM"     denied  "$U" iam:CreateUser "*"
  expect IA-09 "ingestion cannot delete bucket"  denied  "$U" s3:DeleteBucket "$B"
  expect IA-09 "ingestion cannot set bucket policy" denied "$U" s3:PutBucketPolicy "$B"
  for p in $SF_READ_PREFIXES; do
    expect IA-10 "snowflake role can read $p/"   allowed "$R" s3:GetObject "$B/$p/x"
  done
  expect IA-10 "snowflake role cannot read state/" denied "$R" s3:GetObject "$B/state/x"
  expect IA-10 "snowflake role cannot write"     denied  "$R" s3:PutObject "$B/raw/x"
  expect IA-10 "snowflake role cannot delete"    denied  "$R" s3:DeleteObject "$B/raw/x"

  # --- trust ---
  local trust
  trust="$(aws iam get-role --role-name "$SF_ROLE" --query 'Role.AssumeRolePolicyDocument' --output json 2>/dev/null | compact || true)"
  if [ -z "$trust" ]; then
    t_fail IA-11 "role $SF_ROLE missing"
  elif printf '%s' "$trust" | grep -q "$PENDING_EXTERNAL_ID"; then
    t_pend IA-11 "trust still placeholder; run 'snowflake-trust' after manual step M5"
  elif printf '%s' "$trust" | grep -q 'sts:ExternalId' && ! printf '%s' "$trust" | grep -q ":${ACCOUNT_ID}:root"; then
    t_pass IA-11 "role trusted only by Snowflake principal + external ID"
  else
    t_fail IA-11 "unexpected trust policy"
  fi

  # --- real round-trip with the ingestion key ---
  if [ -n "$roundtrip" ]; then
    local kid ksec key vid
    kid="$(env_get AWS_ACCESS_KEY_ID)"; ksec="$(env_get AWS_SECRET_ACCESS_KEY)"
    if [ -z "$kid" ] || [ -z "$ksec" ]; then
      t_fail IA-12 "no ingestion key in $ENV_FILE (run 'keys')"
    else
      key="state/_verify_$(date -u +%Y%m%dT%H%M%SZ).txt"
      if printf 'verify\n' | env -u AWS_PROFILE AWS_ACCESS_KEY_ID="$kid" AWS_SECRET_ACCESS_KEY="$ksec" \
           aws --region "$REGION" s3 cp - "s3://$BUCKET/$key" >/dev/null 2>&1 && \
         env -u AWS_PROFILE AWS_ACCESS_KEY_ID="$kid" AWS_SECRET_ACCESS_KEY="$ksec" \
           aws --region "$REGION" s3 cp "s3://$BUCKET/$key" - 2>/dev/null | grep -q verify; then
        t_pass IA-12 "ingestion key can write and read $key"
      else
        t_fail IA-12 "ingestion key round-trip failed"
      fi
      # Clean-up with the admin profile: delete every version of the test object
      for vid in $(aws_r s3api list-object-versions --bucket "$BUCKET" --prefix "$key" \
                     --query '[Versions[].VersionId, DeleteMarkers[].VersionId][]' --output text 2>/dev/null); do
        [ "$vid" = "None" ] || aws_r s3api delete-object --bucket "$BUCKET" --key "$key" --version-id "$vid" >/dev/null
      done
    fi
    unset kid ksec
  fi

  # --- idempotency ---
  if [ -n "$idem" ]; then
    local out
    out="$(BUDGET_EMAIL="${BUDGET_EMAIL:-unused@example.com}" "$0" setup 2>&1 || true)"
    if printf '%s' "$out" | grep -qE '^  (CREATED|UPDATED)'; then
      t_fail IA-13 "rerun of setup changed something:"; printf '%s\n' "$out" | grep -E '^  (CREATED|UPDATED)'
    else
      t_pass IA-13 "rerun of setup made 0 changes"
    fi
  fi

  # --- secrets ---
  if [ -f "$ENV_FILE" ]; then
    local perm
    perm="$(stat -f '%Lp' "$ENV_FILE" 2>/dev/null || stat -c '%a' "$ENV_FILE")"
    [ "$perm" = "600" ] && t_pass IA-14 "$ENV_FILE is chmod 600" || t_fail IA-14 "$ENV_FILE permissions are $perm, expected 600"
    if git rev-parse --is-inside-work-tree >/dev/null 2>&1; then
      git check-ignore -q "$ENV_FILE" && t_pass IA-14 "$ENV_FILE is git-ignored" || t_fail IA-14 "$ENV_FILE is NOT git-ignored"
      if git ls-files -z | xargs -0 grep -lE 'AKIA[0-9A-Z]{16}' 2>/dev/null | grep -q .; then
        t_fail IA-14 "an AWS access key ID is committed in Git"
      else
        t_pass IA-14 "no AWS access key ID in tracked files"
      fi
    else
      t_pend IA-14 "not a Git repo yet; .gitignore check runs once the repo exists"
    fi
  else
    t_pend IA-14 "$ENV_FILE not found (run 'keys')"
  fi

  say ""
  say "Result: $PASS passed, $FAIL failed, $PEND pending."
  [ "$FAIL" -eq 0 ]
}

# ----------------------------- status ----------------------------------------
cmd_status() {
  cmd_preflight
  say "== Status"
  aws_r s3api head-bucket --bucket "$BUCKET" >/dev/null 2>&1 && say "  bucket   $BUCKET" || say "  bucket   (missing)"
  aws iam get-user --user-name "$INGEST_USER" >/dev/null 2>&1 \
    && say "  user     $INGEST_USER, keys: $(aws iam list-access-keys --user-name "$INGEST_USER" --query 'length(AccessKeyMetadata)' --output text)" \
    || say "  user     (missing)"
  aws iam get-role --role-name "$SF_ROLE" >/dev/null 2>&1 && say "  role     $(role_arn)" || say "  role     (missing)"
  say "  budget   $(aws budgets describe-budget --region us-east-1 --account-id "$ACCOUNT_ID" --budget-name "$BUDGET_NAME" \
                    --query 'Budget.BudgetLimit.Amount' --output text 2>/dev/null || echo '(missing)') USD"
}

# ----------------------------- main ------------------------------------------
case "${1:-}" in
  preflight)        cmd_preflight ;;
  setup)            cmd_setup ;;
  keys)             shift; cmd_keys "${1:-}" ;;
  snowflake-trust)  shift; cmd_snowflake_trust "$@" ;;
  verify)           shift; cmd_verify "$@" ;;
  status)           cmd_status ;;
  all)              cmd_setup; cmd_keys; cmd_verify ;;
  *) awk 'NR>1 && /^#/ {print; next} NR>1 {exit}' "$0"; exit 1 ;;
esac
